package main

import (
	"encoding/json"
	"errors"
	"io/ioutil"
	"os"
	"sort"
	"sync"
)

const tasksFile = "tasks.json"

// Task represents a single todo item.
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// TodoList manages a list of tasks.
type TodoList struct {
	tasks []Task
	mu    sync.Mutex // Mutex to protect access to tasks
}

// NewTodoList creates a new TodoList instance.
func NewTodoList() *TodoList {
	return &TodoList{
		tasks: []Task{},
	}
}

// LoadTasks loads tasks from the tasksFile.
func (tl *TodoList) LoadTasks() error {
	tl.mu.Lock()
	defer tl.mu.Unlock()

	data, err := ioutil.ReadFile(tasksFile)
	if err != nil {
		if os.IsNotExist(err) {
			tl.tasks = []Task{}
			return nil
		}
		return err
	}

	return json.Unmarshal(data, &tl.tasks)
}

// SaveTasks saves tasks to the tasksFile.
func (tl *TodoList) SaveTasks() error {
	tl.mu.Lock()
	defer tl.mu.Unlock()

	data, err := json.MarshalIndent(tl.tasks, "", "  ")
	if err != nil {
		return err
	}

	return ioutil.WriteFile(tasksFile, data, 0644)
}

// AddTask adds a new task to the list.
func (tl *TodoList) AddTask(description string) (Task, error) {
	tl.mu.Lock()
	defer tl.mu.Unlock()

	id := 1
	if len(tl.tasks) > 0 {
		// Find the maximum ID and increment it for the new task
		sort.Slice(tl.tasks, func(i, j int) bool {
			return tl.tasks[i].ID < tl.tasks[j].ID
		})
		id = tl.tasks[len(tl.tasks)-1].ID + 1
	}

	task := Task{
		ID:          id,
		Description: description,
		Done:        false,
	}
	tl.tasks = append(tl.tasks, task)

	return task, nil
}

// ListPendingTasks returns all pending tasks.
func (tl *TodoList) ListPendingTasks() []Task {
	tl.mu.Lock()
	defer tl.mu.Unlock()

	var pending []Task
	for _, task := range tl.tasks {
		if !task.Done {
			pending = append(pending, task)
		}
	}
	return pending
}

// CompleteTask marks a task as done by its ID.
func (tl *TodoList) CompleteTask(id int) (Task, error) {
	tl.mu.Lock()
	defer tl.mu.Unlock()

	for i, task := range tl.tasks {
		if task.ID == id {
			tl.tasks[i].Done = true
			return tl.tasks[i], nil
		}
	}
	return Task{}, errors.New("task not found")
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strconv"
)

func main() {
	// Initialize a new TodoList
	tl := NewTodoList()

	// Load existing tasks
	err := tl.LoadTasks()
	if err != nil {
		printErrorAndExit(err, 1)
	}

	if len(os.Args) < 2 {
		printErrorAndExit(fmt.Errorf("no command provided"), 42)
	}

	command := os.Args[1]

	switch command {
	case "add":
		addCmd := flag.NewFlagSet("add", flag.ExitOnError)
		description := addCmd.String("description", "", "Task description")
		addCmd.Parse(os.Args[2:])

		if *description == "" {
			// If the description flag is not used, try to get it from positional arguments
			if len(addCmd.Args()) > 0 {
				*description = addCmd.Args()[0]
			}
		}

		if *description == "" {
			printErrorAndExit(fmt.Errorf("missing task description"), 42)
		}

		task, err := tl.AddTask(*description)
		if err != nil {
			printErrorAndExit(err, 1)
		}

		err = tl.SaveTasks()
		if err != nil {
			printErrorAndExit(err, 1)
		}

		printJSON("id", task.ID, "status", "added")

	case "list":
		listCmd := flag.NewFlagSet("list", flag.ExitOnError)
		listCmd.Parse(os.Args[2:])

		tasks := tl.ListPendingTasks()
		printJSONTasks(tasks)

	case "done":
		doneCmd := flag.NewFlagSet("done", flag.ExitOnError)
		idStr := doneCmd.String("id", "0", "Task ID")
		doneCmd.Parse(os.Args[2:])

		id := 0
		if *idStr == "0" {
			// If the id flag is not used, try to get it from positional arguments
			if len(doneCmd.Args()) > 0 {
				id, err = strconv.Atoi(doneCmd.Args()[0])
				if err != nil {
					printErrorAndExit(fmt.Errorf("invalid task ID"), 42)
				}
			}
		}

		if id == 0 {
			printErrorAndExit(fmt.Errorf("missing task ID"), 42)
		}

		task, err := tl.CompleteTask(id)
		if err != nil {
			printErrorAndExit(err, 1)
		}

		err = tl.SaveTasks()
		if err != nil {
			printErrorAndExit(err, 1)
		}

		printJSON("id", task.ID, "status", "completed")

	default:
		printErrorAndExit(fmt.Errorf("unknown command: %s", command), 42)
	}
}

func printJSON(args ...interface{}) {
	data := make(map[string]interface{})
	for i := 0; i < len(args); i += 2 {
		key, ok := args[i].(string)
		if !ok {
			// This should not happen with correct usage
			continue
		}
		data[key] = args[i+1]
	}
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	encoder.Encode(data)
}

func printJSONTasks(tasks []Task) {
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	encoder.Encode(tasks)
}

func printErrorAndExit(err error, code int) {
	response := map[string]string{"error": err.Error()}
	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	encoder.Encode(response)
	os.Exit(code)
}

package main

import (
	"encoding/json"
	"io/ioutil"
	"os"
	"testing"
)

func TestMain(m *testing.M) {
	// Run tests
	exitCode := m.Run()

	// Clean up after tests
	os.Remove(tasksFile)
	os.Exit(exitCode)
}

func TestLoadTasks_FileDoesNotExist(t *testing.T) {
	// Ensure tasks.json does not exist before test
	os.Remove(tasksFile)

	tl := NewTodoList()
	err := tl.LoadTasks()
	if err != nil {
		t.Fatalf("Expected no error for non-existent file, got: %v", err)
	}

	if len(tl.tasks) != 0 {
		t.Errorf("Expected empty tasks, got %d tasks", len(tl.tasks))
	}
}

func TestSaveAndLoadTasks(t *testing.T) {
	// Ensure tasks.json does not exist before test
	os.Remove(tasksFile)

	tl := NewTodoList()

	// Add some tasks
	_, _ = tl.AddTask("Task 1")
	_, _ = tl.AddTask("Task 2")

	// Save tasks
	err := tl.SaveTasks()
	if err != nil {
		t.Fatalf("Failed to save tasks: %v", err)
	}

	// Create a new TodoList and load tasks
	newTl := NewTodoList()
	err = newTl.LoadTasks()
	if err != nil {
		t.Fatalf("Failed to load tasks: %v", err)
	}

	// Verify loaded tasks
	if len(newTl.tasks) != 2 {
		t.Errorf("Expected 2 tasks, got %d", len(newTl.tasks))
	}

	if newTl.tasks[0].Description != "Task 1" || newTl.tasks[1].Description != "Task 2" {
		t.Errorf("Loaded tasks do not match original")
	}
}

func TestAddTask(t *testing.T) {
	// Ensure tasks.json does not exist before test
	os.Remove(tasksFile)

	tl := NewTodoList()

	task1, err := tl.AddTask("First task")
	if err != nil {
		t.Fatalf("Failed to add task: %v", err)
	}

	if task1.ID != 1 || task1.Description != "First task" || task1.Done != false {
		t.Errorf("Unexpected task1: %+v", task1)
	}

	task2, err := tl.AddTask("Second task")
	if err != nil {
		t.Fatalf("Failed to add task: %v", err)
	}

	if task2.ID != 2 || task2.Description != "Second task" || task2.Done != false {
		t.Errorf("Unexpected task2: %+v", task2)
	}

	if len(tl.tasks) != 2 {
		t.Errorf("Expected 2 tasks in list, got %d", len(tl.tasks))
	}
}

func TestListPendingTasks(t *testing.T) {
	// Ensure tasks.json does not exist before test
	os.Remove(tasksFile)

	tl := NewTodoList()
	task1, _ := tl.AddTask("Task 1")
	task2, _ := tl.AddTask("Task 2")
	task3, _ := tl.AddTask("Task 3")

	// Complete task2
	_, err := tl.CompleteTask(task2.ID)
	if err != nil {
		t.Fatalf("Failed to complete task: %v", err)
	}

	pendingTasks := tl.ListPendingTasks()

	if len(pendingTasks) != 2 {
		t.Errorf("Expected 2 pending tasks, got %d", len(pendingTasks))
	}

	if pendingTasks[0].ID != task1.ID || pendingTasks[1].ID != task3.ID {
		t.Errorf("Unexpected pending tasks: %+v", pendingTasks)
	}
}

func TestCompleteTask(t *testing.T) {
	// Ensure tasks.json does not exist before test
	os.Remove(tasksFile)

	tl := NewTodoList()
	task1, _ := tl.AddTask("Task to complete")
	_, _ = tl.AddTask("Another task")

	completedTask, err := tl.CompleteTask(task1.ID)
	if err != nil {
		t.Fatalf("Failed to complete task: %v", err)
	}

	if completedTask.ID != task1.ID || completedTask.Done != true {
		t.Errorf("Expected task1 to be completed, got: %+v", completedTask)
	}

	// Verify the task in the internal list is also updated
	found := false
	for _, task := range tl.tasks {
		if task.ID == task1.ID {
			found = true
			if !task.Done {
				t.Errorf("Task in list not marked as done after completion")
			}
			break
		}
	}
	if !found {
		t.Errorf("Completed task not found in the list")
	}

	// Test completing a non-existent task
	_, err = tl.CompleteTask(999)
	if err == nil {
		t.Errorf("Expected error for non-existent task, got nil")
	}
	if err.Error() != "task not found" {
		t.Errorf("Expected 'task not found' error, got: %v", err)
	}
}

func TestConcurrency(t *testing.T) {
	// Ensure tasks.json does not exist before test
	os.Remove(tasksFile)

	tl := NewTodoList()

	// Add initial tasks
	_, _ = tl.AddTask("Initial task 1")
	_, _ = tl.AddTask("Initial task 2")

	// Save initial tasks
	err := tl.SaveTasks()
	if err != nil {
		t.Fatalf("Failed to save initial tasks: %v", err)
	}

	numGoroutines := 10
	var wg sync.WaitGroup
	wg.Add(numGoroutines)

	for i := 0; i < numGoroutines; i++ {
		go func(i int) {
			defer wg.Done()

			// Each goroutine tries to add a task, complete a task, list tasks, and save
			_, err := tl.AddTask(fmt.Sprintf("Concurrent task %d", i))
			if err != nil {
				t.Errorf("Goroutine %d: Failed to add task: %v", i, err)
			}

			// Try to complete an existing task (e.g., the first one added, ID 1 or 2)
			// This might fail if another goroutine completes it, but we're testing mutex protection for data consistency
			_, err = tl.CompleteTask(1)
			if err != nil && err.Error() != "task not found" { // task not found is expected if already completed
				t.Errorf("Goroutine %d: Failed to complete task: %v", i, err)
			}

			_ = tl.ListPendingTasks() // Just call to ensure no panic

			err = tl.SaveTasks()
			if err != nil {
				t.Errorf("Goroutine %d: Failed to save tasks: %v", i, err)
			}
		}(i)
	}

	wg.Wait()

	// Load tasks again to check final state consistency
	finalTl := NewTodoList()
	err = finalTl.LoadTasks()
	if err != nil {
		t.Fatalf("Failed to load tasks after concurrency test: %v", err)
	}

	// Check if the number of tasks is as expected (initial 2 + numGoroutines added)
	if len(finalTl.tasks) != 2 + numGoroutines {
		t.Errorf("Expected %d tasks after concurrency, got %d", 2+numGoroutines, len(finalTl.tasks))
	}

	// Verify all tasks have unique IDs and descriptions
	ids := make(map[int]bool)
	descriptions := make(map[string]bool)
	for _, task := range finalTl.tasks {
		if ids[task.ID] {
			t.Errorf("Duplicate task ID found: %d", task.ID)
		}
		ids[task.ID] = true

		if descriptions[task.Description] {
			t.Errorf("Duplicate task description found: %s", task.Description)
		}
		descriptions[task.Description] = true
	}

	// Ensure at least one task is marked done (from completing task ID 1)
	oneTaskDone := false
	for _, task := range finalTl.tasks {
		if task.ID == 1 && task.Done {
			oneTaskDone = true
			break
		}
	}
	if !oneTaskDone {
		t.Errorf("Expected task ID 1 to be marked done by at least one goroutine")
	}
}

